pub fn (q PetQuery) min_owner_id() !f64 {
	return load.aggregate_where(q.graph.client.conn, 'pets', 'id', q.graph.client.prepare_query('pets', q.query)!, .min, 'owner_id')
}

// max_owner_id returns the max of `owner_id` over the matching rows, in one
// query; 0 when none has a value.
pub fn (q PetQuery) max_owner_id() !f64 {
	return load.aggregate_where(q.graph.client.conn, 'pets', 'id', q.graph.client.prepare_query('pets', q.query)!, .max, 'owner_id')
}

// mean_owner_id returns the mean of `owner_id` over the matching rows, in one
// query; 0 when none has a value.
pub fn (q PetQuery) mean_owner_id() !f64 {
	return load.aggregate_where(q.graph.client.conn, 'pets', 'id', q.graph.client.prepare_query('pets', q.query)!, .avg, 'owner_id')
}

// PetGroupBy groups the rows of a `PetQuery`. Start one with `group_by`.
pub struct PetGroupBy {
	query PetQuery
pub:
	columns    []string
	aggregates []load.Aggregate
}

// group_by groups the matching rows by `columns`. It needs a vgraph driver.
pub fn (q PetQuery) group_by(columns ...string) PetGroupBy {
	return PetGroupBy{
		query:   q
		columns: columns
	}
}

// aggregate adds what each group gets, such as `vgraph.count()` or
// `vgraph.sum('views')`.
pub fn (g PetGroupBy) aggregate(aggregates ...load.Aggregate) PetGroupBy {
	mut all := g.aggregates.clone()
	all << aggregates
	return PetGroupBy{
		...g
		aggregates: all
	}
}

// all returns the groups, ordered by their columns.
pub fn (g PetGroupBy) all() ![]load.Group {
	q := g.query
	return load.group_where(q.graph.client.conn, 'pets', q.graph.client.prepare_query('pets', q.query)!, g.columns.map(load.GroupColumn{
		name: it
		typ:  pet_column_type(it)
	}), g.aggregates)
}

// scan reads the groups into `T`, by name: its fields named after the grouped
// columns and the aggregates (`count`, `sum_views`).
pub fn (g PetGroupBy) scan[T]() ![]T {
	return load.scan_groups[T](g.all()!)
}

// pet_column_type returns the V type of a column of `pets`.
fn pet_column_type(column string) string {
	return match column {
		'id' { 'int' }
		'name' { 'string' }
		'owner_id' { '?int' }
		'deleted_at' { '?time.Time' }
		else { '' }
	}
}

// order_by_owner_name orders the rows by the `name` of their `owner`.
pub fn (q PetQuery) order_by_owner_name() PetQuery {
	return q.order_by(load.Order{
		expr: '(SELECT "t1"."name" FROM "users" AS "t1" WHERE "t1"."id" = "t0"."owner_id")'
	})
}

// order_by_owner_name_desc orders the rows by the `name` of their
// `owner`, descending.
pub fn (q PetQuery) order_by_owner_name_desc() PetQuery {
	return q.order_by(load.Order{
		expr: '(SELECT "t1"."name" FROM "users" AS "t1" WHERE "t1"."id" = "t0"."owner_id")'
		desc: true
	})
}

// order_by_owner_spouse_id orders the rows by the `spouse_id` of their `owner`.
pub fn (q PetQuery) order_by_owner_spouse_id() PetQuery {
	return q.order_by(load.Order{
		expr: '(SELECT "t1"."spouse_id" FROM "users" AS "t1" WHERE "t1"."id" = "t0"."owner_id")'
	})
}

// order_by_owner_spouse_id_desc orders the rows by the `spouse_id` of their
