// with_owner loads each row's `owner` (many_to_one `users`) with it, in one
// query for all the rows. `configure` narrows them, and can load their edges.
pub fn (q PetQuery) with_owner(configure ...fn (UserQuery) UserQuery) PetQuery {
	mut next := q
	next.with_owner = true
	next.owner_fns = configure
	return next
}

// all returns the matching rows, with the requested edges.
pub fn (q PetQuery) all() ![]PetNode {
	rows := load.select_where[models.Pet](q.graph.client.conn, q.graph.client.prepare_query('pets', q.query)!)!
	return q.nodes(rows)
}

// first returns the first matching row, with the requested edges, or a
// `NotFoundError`.
pub fn (q PetQuery) first() !PetNode {
	nodes := q.limit(1).all()!
	if nodes.len == 0 {
		return NotFoundError{
			table: 'pets'
		}
	}
	return nodes[0]
}

// nodes loads the requested edges onto `rows`, which the caller already has: one
// query per edge, however many rows there are.
pub fn (q PetQuery) nodes(rows []models.Pet) ![]PetNode {
	mut nodes := rows.map(PetNode{
		graph: q.graph
		pet:   it
	})
	if q.with_owner {
		found := q.load_owner(rows, q.owner_fns)!
		for mut node in nodes {
			// at most one each: the first, in the order of the query
			list := found[node.pet.id.str()] or { [] }
			if list.len > 0 {
				node.owner = &UserNode{
					...list[0]
				}
			}
			node.loaded << 'owner'
		}
	}
	return nodes
}

// load_owner loads the `owner` of `rows`, keyed by each row's key.
fn (q PetQuery) load_owner(rows []models.Pet, fns []fn (UserQuery) UserQuery) !map[string][]UserNode {
	mut sub := q.graph.users()
	for configure in fns {
		sub = configure(sub)
	}
	mut keys := []string{}
	for row in rows {
		if fk := row.owner_id {
			keys << fk.str()
		}
	}
	targets := sub.nodes(load.select_in[models.User](q.graph.client.conn, 'id', load.unique(keys),
		query: q.graph.client.prepare_query('users', sub.query)!
	)!)!
	mut by_key := map[string]UserNode{}
	for target in targets {
		by_key[target.user.id.str()] = target
	}
	mut found := map[string][]UserNode{}
	for row in rows {
		fk := row.owner_id or { continue }
		if target := by_key[fk.str()] {
			found[row.id.str()] = [target]
		}
	}
	return found
}

// owner_or_err returns the `owner`: a `NotLoadedError` when the query didn't
// load it, a `NotFoundError` when the row has none.
pub fn (n PetNode) owner_or_err() !&UserNode {
	if 'owner' !in n.loaded {
		return NotLoadedError{
			edge: 'pets.owner'
		}
	}
	if target := n.owner {
		return target
	}
	return NotFoundError{
		table: 'users'
	}
}

// query_owner starts a query of this row's `owner`, which matches
// nothing when the row has none.
pub fn (n PetNode) query_owner() UserQuery {
	key := n.pet.owner_id or { return n.graph.users().where(load.in_ints('id', [])) }
	return n.graph.users().where(load.eq('id', key))
}
